// Bakes the Bannerhold texture library from the pure generators in
// shared/legacy/environment/textures into main game/public/assets/legacy/environment/textures/:
// <set>-<map>.webp at the set's desktop-high size and <set>-<map>-512.webp for medium,
// low and Quest, plus manifest.json (tile size, mean luminance, sha256 per file).
// Original procedural content generated by this script; no external images.
// Run: main-game-vr/node_modules/.bin/tsx scripts/generate-legacy-environment-textures.ts [--only ashlar,slate] [--png]
// WebP encoding uses sharp from main-game-vr/node_modules when present; otherwise PNG.

import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { deflateSync } from "node:zlib";
import { TEXTURE_SETS } from "../shared/legacy/environment/materials/library";
import { downsample2, downsampleNormal2, finishTexture } from "../shared/legacy/environment/textures/field";
import { generateTextureFields } from "../shared/legacy/environment/textures/generators";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const TEXTURE_OUT = join(root, "main game/public/assets/legacy/environment/textures");

type Sharp = (input: Buffer, opts: { raw: { width: number; height: number; channels: 4 } }) => {
  removeAlpha(): { webp(o: { quality: number; effort: number; smartSubsample?: boolean }): { toBuffer(): Promise<Buffer> } };
};

function loadSharp(): Sharp | null {
  for (const base of [join(root, "main-game-vr/package.json"), join(root, "main game/package.json")]) {
    try {
      const req = createRequire(base);
      return req("sharp") as Sharp;
    } catch {
      // try the next location
    }
  }
  return null;
}

const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32(buf: Buffer): number {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function chunk(type: string, data: Buffer): Buffer {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const td = Buffer.concat([Buffer.from(type, "ascii"), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(td));
  return Buffer.concat([len, td, crc]);
}

/** Minimal deterministic RGB PNG encoder. */
export function encodePng(rgba: Uint8ClampedArray, size: number): Buffer {
  const raw = Buffer.alloc((size * 3 + 1) * size);
  for (let y = 0; y < size; y++) {
    const o = y * (size * 3 + 1);
    raw[o] = 0;
    for (let x = 0; x < size; x++) {
      raw[o + 1 + x * 3] = rgba[(y * size + x) * 4];
      raw[o + 2 + x * 3] = rgba[(y * size + x) * 4 + 1];
      raw[o + 3 + x * 3] = rgba[(y * size + x) * 4 + 2];
    }
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0);
  ihdr.writeUInt32BE(size, 4);
  ihdr[8] = 8;
  ihdr[9] = 2;
  ihdr[10] = 0;
  ihdr[11] = 0;
  ihdr[12] = 0;
  return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk("IHDR", ihdr), chunk("IDAT", deflateSync(raw, { level: 9 })), chunk("IEND", Buffer.alloc(0))]);
}

async function encode(sharp: Sharp | null, rgba: Uint8ClampedArray, size: number, map: string): Promise<{ data: Buffer; ext: string }> {
  if (!sharp) return { data: encodePng(rgba, size), ext: "png" };
  const data = await sharp(Buffer.from(rgba.buffer, rgba.byteOffset, rgba.byteLength), { raw: { width: size, height: size, channels: 4 } })
    .removeAlpha()
    .webp({ quality: map === "normal" ? 92 : 88, effort: 5, smartSubsample: map === "albedo" })
    .toBuffer();
  return { data, ext: "webp" };
}

interface ManifestFile {
  file: string;
  size: number;
  sha256: string;
}

export async function generateLegacyEnvironmentTextures(opts: { only?: string[]; png?: boolean } = {}): Promise<void> {
  const sharp = opts.png ? null : loadSharp();
  mkdirSync(TEXTURE_OUT, { recursive: true });
  const manifestPath = join(TEXTURE_OUT, "manifest.json");
  const previous = existsSync(manifestPath) ? (JSON.parse(readFileSync(manifestPath, "utf8")) as { sets: Record<string, unknown> }) : { sets: {} };
  const sets: Record<string, { tileMetres: number; meanLuminance: number; files: Record<string, ManifestFile> }> = {};
  for (const recipe of TEXTURE_SETS) {
    if (opts.only && opts.only.indexOf(recipe.id) < 0) {
      if (previous.sets[recipe.id]) sets[recipe.id] = previous.sets[recipe.id] as (typeof sets)[string];
      continue;
    }
    const t0 = Date.now();
    const img = finishTexture(generateTextureFields(recipe, recipe.highSize));
    const files: Record<string, ManifestFile> = {};
    const write = async (map: "albedo" | "normal" | "orm", rgba: Uint8ClampedArray, size: number, suffix: string): Promise<void> => {
      const { data, ext } = await encode(sharp, rgba, size, map);
      const file = `${recipe.id}-${map}${suffix}.${ext}`;
      writeFileSync(join(TEXTURE_OUT, file), data);
      files[`${map}${suffix ? "_512" : ""}`] = { file, size, sha256: createHash("sha256").update(data).digest("hex") };
    };
    for (const map of ["albedo", "normal", "orm"] as const) {
      const src = img[map];
      if (recipe.highSize === 1024) {
        await write(map, src, 1024, "");
        await write(map, map === "normal" ? downsampleNormal2(src, 1024) : downsample2(src, 1024), 512, "-512");
      } else {
        await write(map, src, 512, "-512");
      }
    }
    sets[recipe.id] = { tileMetres: recipe.tileMetres, meanLuminance: Math.round(img.meanLuminance * 10000) / 10000, files };
    process.stdout.write(`${recipe.id}: ${recipe.highSize}px in ${Date.now() - t0} ms\n`);
  }
  const manifest = {
    version: 1,
    generator: "scripts/generate-legacy-environment-textures.ts",
    provenance: "Original procedural textures generated from shared/legacy/environment/textures (no external images).",
    encoder: sharp ? "webp (sharp)" : "png (zlib)",
    sets,
  };
  writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + "\n");
}

if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  const onlyArg = process.argv.indexOf("--only");
  const only = onlyArg > 0 ? process.argv[onlyArg + 1].split(",") : undefined;
  generateLegacyEnvironmentTextures({ only, png: process.argv.indexOf("--png") > 0 }).catch((e) => {
    console.error(e);
    process.exit(1);
  });
}
